test('addLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = result.value;
  const originalLength = invoice.lines.length;
  const originalQty = invoice.lines[0].qty;

  addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(invoice.lines.length, originalLength);
  assert.equal(invoice.lines[0].qty, originalQty);
});

test('removeLine removes a line by SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const invoice = result.value;

  const removeResult = removeLine(invoice, 'LOGO-PACK');
  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
});

