test('addLine and removeLine chain correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  let invoice = result.value;

  const add1 = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(add1.ok, true);
  invoice = add1.value;
  assert.equal(invoice.lines.length, 2);

  const add2 = addLine(invoice, { sku: 'COPY-HOUR', qty: 3 });
  assert.equal(add2.ok, true);
  invoice = add2.value;
  assert.equal(invoice.lines.length, 3);

  const remove = removeLine(invoice, 'LOGO-PACK');
  assert.equal(remove.ok, true);
  invoice = remove.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});
